// Build the full Gemini generateContent request body (JSON string) for the
// HTTP node. Uses the structured-output schema so gemini-2.5-flash always
// returns parseable JSON with every required field.
const row = $('Get Next Keyword').item.json;
const keyword = String(row.Keyword || '').trim();
const audience = String(row.Target_Audience || 'general').trim();

const prompt = `You are the senior SEO content strategist for ShadowTalk AI (https://www.shadowtalk-ai.com) — a free, privacy-first agentic AI workspace: encrypted multi-model chat with BYOK (bring your own key) across 16+ providers (OpenAI, Anthropic, Google, Groq, DeepSeek, OpenRouter and more), ProofLoop verifiable missions, deep research with cited sources, voice mode, an agentic IDE, and an optional on-device WebGPU model that runs offline in the browser. ShadowTalk never resells AI inference: BYOK requests go browser-to-provider, keys stay in the user's browser, and there is no subscription or credit card.

Write a marketing content package for this search query: "${keyword}"
Target audience: "${audience}"

Hard rules:
- Facts only. Never invent statistics, quotes, dates, pricing or competitor claims. Any landscape statement must be framed as of 2026. The only ShadowTalk claims you may make are the product facts in this prompt.
- The article must be 1,000+ words, structured with ## H2 and ### H3 headings, include at least one numbered step list, one "How ShadowTalk fits" subsection with ONE natural product mention (no hard sell), and a closing "## FAQ" section with at least four ### H3 questions and concise answers.
- markdown_article starts with an ## H2 (the H1 title is rendered separately from seo_title). Do not repeat the title as an H1 inside the article.
- seo_title: under 60 characters, front-load the keyword. meta_description: under 155 characters, ends with a call to discover more.
- slug: lowercase, hyphenated, 3-6 words, URL-safe, ASCII only.
- linkedin_post: 120-200 words — opening hook line, three short insight bullets ("• "), and a soft CTA pointing to https://www.shadowtalk-ai.com
- x_thread_hook: exactly 3 tweets separated by blank lines. Tweet 1 = punchy hook (under 200 chars, no hashtag spam). Tweet 2 = the core insight. Tweet 3 = takeaway + link https://www.shadowtalk-ai.com
- video_script_lines: exactly 5 strings, each 12 words maximum, spoken-word style for a 25-second vertical video, hook first, CTA last.

Return ONLY the JSON object matching the response schema — no markdown fences, no commentary.`;

const body = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.8,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      properties: {
        slug: { type: 'string' },
        seo_title: { type: 'string' },
        meta_description: { type: 'string' },
        markdown_article: { type: 'string' },
        linkedin_post: { type: 'string' },
        x_thread_hook: { type: 'string' },
        video_script_lines: { type: 'array', items: { type: 'string' } },
      },
      required: ['slug', 'seo_title', 'meta_description', 'markdown_article', 'linkedin_post', 'x_thread_hook', 'video_script_lines'],
    },
  },
};

return [{ json: { geminiRequestBody: JSON.stringify(body) } }];

// Safely extract Gemini's JSON answer from candidates[0].content.parts[0].text
const item = $input.first();
const payload = item.json || {};
const candidates = Array.isArray(payload.candidates) ? payload.candidates : [];
const parts = (candidates[0] && candidates[0].content && candidates[0].content.parts) || [];
const raw = parts.map((p) => p.text || '').join('').trim();

if (!raw) {
  const reason = (candidates[0] && candidates[0].finishReason) || 'unknown';
  const block = payload.promptFeedback && payload.promptFeedback.blockReason;
  throw new Error(`Gemini returned no text (finishReason=${reason}${block ? ', blockReason=' + block : ''}). Check GEMINI_API_KEY quota and model availability.`);
}

// Strip optional ```json fences, then parse — with a brace-slice fallback.
let cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (firstError) {
  const start = cleaned.indexOf('{');
  const end = cleaned.lastIndexOf('}');
  if (start === -1 || end <= start) {
    throw new Error('Gemini output is not valid JSON: ' + cleaned.slice(0, 200));
  }
  parsed = JSON.parse(cleaned.slice(start, end + 1));
}

const REQUIRED = ['slug', 'seo_title', 'meta_description', 'markdown_article', 'linkedin_post', 'x_thread_hook', 'video_script_lines'];
const missing = REQUIRED.filter((k) => parsed[k] === undefined || parsed[k] === null || parsed[k] === '');
if (missing.length) {
  throw new Error('Gemini JSON missing required fields: ' + missing.join(', '));
}

// Normalise video_script_lines: accept an array or a newline-separated string.
if (!Array.isArray(parsed.video_script_lines) || parsed.video_script_lines.length < 3) {
  parsed.video_script_lines = String(parsed.video_script_lines || '')
    .split('\n')
    .map((s) => s.replace(/^\s*(?:\d+[.)]|[-•*])\s*/, '').trim())
    .filter(Boolean)
    .slice(0, 8);
}
if (!Array.isArray(parsed.video_script_lines) || parsed.video_script_lines.length < 3) {
  throw new Error('video_script_lines has fewer than 3 usable lines — regenerate.');
}

// Carry the queue row metadata forward so downstream nodes never re-look it up.
parsed.Keyword = $('Get Next Keyword').item.json.Keyword;
parsed.Target_Audience = $('Get Next Keyword').item.json.Target_Audience || '';

return [{ json: parsed }];

// Build the YAML-frontmatter Markdown file for content/blog/<slug>.md.
// Keys mirror the blog reader contract in src/lib/blog.ts.
const item = $input.first().json;
const q = (v) => String(v ?? '').replace(/"/g, '\\"');
const blogMarkdown = [
  '---',
  `slug: "${q(item.slug)}"`,
  `title: "${q(item.seo_title)}"`,
  `description: "${q(item.meta_description)}"`,
  `date: "${$now.toFormat('yyyy-MM-dd')}"`,
  `keyword: "${q(item.Keyword)}"`,
  `audience: "${q(item.Target_Audience)}"`,
  '---',
  '',
  String(item.markdown_article || '').trim(),
  '',
].join('\n');

return [{ json: { slug: item.slug, blog_markdown: blogMarkdown } }];
